INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl speichert "INSERT INTO employees (id, name) VALUES (1, ''Anna'')" dauerhaft? "COMMIT"?', 2, '[{"text": "COMMIT", "correct": true, "because": "Bestätigt Transaktion"}, {"text": "ROLLBACK", "correct": false, "because": "Macht rückgängig"}, {"text": "SAVEPOINT", "correct": false, "because": "Nur Rückpunkt"}]'),
