('00000000-0000-0000-0000-000000000000', 'Welcher Befehl setzt einen Rückpunkt nach "DELETE FROM tasks WHERE id = 5"? "SAVEPOINT sp1"?', 4, '[{"text": "SAVEPOINT", "correct": true, "because": "Markiert Transaktionspunkt"}, {"text": "COMMIT", "correct": false, "because": "Speichert dauerhaft"}, {"text": "ROLLBACK", "correct": false, "because": "Setzt zurück"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei "ROLLBACK TO SAVEPOINT sp1" nach "INSERT INTO products (id, price) VALUES (101, 29.99); SAVEPOINT sp1; UPDATE products SET price = 39.99 WHERE id = 101"?', 5, '[{"text": "Stellt price auf 29.99 zurück", "correct": true, "because": "Zurück zu sp1"}, {"text": "Speichert price als 39.99", "correct": false, "because": "Kein COMMIT"}, {"text": "Löscht Datensatz 101", "correct": false, "because": "Kein DELETE"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl bestätigt "UPDATE employees SET salary = 60000 WHERE id = 10"? "COMMIT"?', 2, '[{"text": "COMMIT", "correct": true, "because": "Macht Änderung permanent"}, {"text": "ROLLBACK", "correct": false, "because": "Setzt zurück"}, {"text": "DROP", "correct": false, "because": "Kein TCL"}]'),
